import tensorflow as tf

def forward_data_based_on_pred(data, pred):
    # Use tf.raw_ops.Switch to forward the data to the appropriate output based on the condition pred
    outputs = tf.raw_ops.Switch(data=data, pred=pred)
    return outputs

# Example usage:
# Assuming `data` is a tensor and `pred` is a boolean tensor determining which output port to use.
data = tf.constant([10, 20, 30])
pred = tf.constant(True)
result = forward_data_based_on_pred(data, pred)

# Printing the outputs generated by the Switch operation
print("True branch output:", result[0].numpy())
print("False branch output:", result[1].numpy())
